INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('everyday-cancel-amazon-prime', 'everyday-spending', '6a8578266d00107b3bf3f481', 'Cancel Amazon Prime', 'One account, six companies you''re also funding.', 'Prime membership funds Amazon''s retail, logistics, cloud, advertising, and media arms in one subscription. Cancelling it is a five-minute account setting, not a boycott of every seller who happens to list there.', 'Withdraw', 'Easy', '5 Minutes', 'Anywhere', '[0, 70, 140]', '[{"label": "Goods Unite Us", "url": "https://www.goodsuniteus.com/"}]', 1, 1);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('everyday-swap-household-aisle', 'everyday-spending', '6a8578266d00107b3bf3f481', 'Swap the household aisle', 'Detergent, toothpaste, razors. Done once, done forever.', 'A handful of purchases repeat every month without a second thought — laundry, dish, and personal care basics. Pick one replacement brand for each and the switch never has to be re-decided.', 'Substitute', 'Easy', '10-30 Minutes', 'Anywhere', '[0, 20, 50]', '[{"label": "Ethical Consumer", "url": "https://www.ethicalconsumer.org/"}]', 0, 2);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('everyday-learn-brand-ownership', 'everyday-spending', '6a8578266d00107b3bf3f481', 'Learn who owns your brands', 'Twenty minutes on the ten things you buy most. Then you never look it up again.', 'A dozen conglomerates own most of what''s on a supermarket shelf. Angel Soft is Koch. Oreo and Philadelphia are Mondelez. Oral-B and Gillette are Procter & Gamble. Spend twenty minutes learning the ownership tree for the ten things you buy most — after that you stop needing to check, and you can explain it to other people.', 'Withdraw', 'Easy', '10-30 Minutes', 'Anywhere', '[]', '[{"label": "Goods Unite Us", "url": "https://www.goodsuniteus.com/"}, {"label": "Ethical Consumer", "url": "https://www.ethicalconsumer.org/"}]', 0, 3);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('everyday-research-companies', 'everyday-spending', '6a21ee990086a37d9b8f28e7', 'Research a company before you spend', 'Ownership, ethics, and political donations — before checkout, not after.', 'Ethical Consumer, Goods Unite Us, OpenSecrets, and product-origin scanners can tell you who you''re paying and what they fund, before you''ve committed to the purchase.', 'Build', 'Easy', 'Ongoing', 'Anywhere', '[]', '[{"label": "Ethical Consumer", "url": "https://www.ethicalconsumer.org/"}]', 0, 4);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('everyday-switch-grocery-retailer', 'everyday-spending', '6a8578266d00107b3bf3f481', 'Switch your regular grocery retailer', 'Move your default cart to a co-op or independent grocer.', 'Most grocery spending goes on autopilot to whichever store is closest or already saved in an app. Picking a different default — a co-op, a regional chain, a local market — redirects a recurring, not one-time, amount.', 'Substitute', 'Moderate', '10-30 Minutes', 'Anywhere', '[0, 100, 250]', '[]', 1, 5);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('everyday-redirect-local-purchase', 'everyday-spending', '6a8578266d00107b3bf3f481', 'Redirect one purchase to a local business', 'Pick one thing you''d normally buy from a large retailer and buy it local instead.', 'Doesn''t have to be everything, every time. One redirected purchase — a gift, a repair, a specialty item — is real money that went somewhere else.', 'Substitute', 'Easy', '10-30 Minutes', 'Anywhere', '[0, 25, 60]', '[]', 0, 6);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('subs-audit-recurring', 'subscriptions', '6a8578266d00107b3bf3f483', 'Audit every recurring subscription', 'One sitting, one list, one clear picture of what''s billing you.', 'Bank and card statements make this a fifteen-minute exercise: list every recurring charge, then decide, cancel, or replace each one deliberately instead of by inertia.', 'Build', 'Moderate', '10-30 Minutes', 'Anywhere', '[]', '[{"label": "European Alternatives", "url": "https://european-alternatives.eu/"}]', 0, 1);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('subs-cancel-netflix', 'subscriptions', '6a8578266d00107b3bf3f483', 'Cancel Netflix', 'One streaming subscription, cancelled or paused.', 'A settings-page cancellation. Note what, if anything, replaced it — that''s the part worth sharing.', 'Withdraw', 'Easy', '5 Minutes', 'Anywhere', '[0, 130, 200]', '[]', 1, 2);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('subs-cancel-disney', 'subscriptions', '6a8578266d00107b3bf3f483', 'Cancel Disney+', 'One streaming subscription, cancelled or paused.', 'A settings-page cancellation. Note what, if anything, replaced it — that''s the part worth sharing.', 'Withdraw', 'Easy', '5 Minutes', 'Anywhere', '[0, 90, 150]', '[]', 1, 3);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('subs-cancel-other-streaming', 'subscriptions', '6a8578266d00107b3bf3f483', 'Cancel another streaming service', 'Max, Paramount+, Apple TV+ — whichever one you''re not watching.', 'The third one is usually the easiest: the one you forgot you still had.', 'Withdraw', 'Easy', '5 Minutes', 'Anywhere', '[0, 100, 180]', '[]', 1, 4);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('subs-switch-cloud-storage', 'subscriptions', '6a8578266d00107b3bf3f483', 'Move your cloud storage', 'Photos and files, migrated to an EU-based or nonprofit provider.', 'The migration is the only real friction — most providers have a straightforward export/import path. Do it once and the monthly charge simply moves.', 'Substitute', 'Moderate', '1-2 Hours', 'Anywhere', '[0, 60, 110]', '[{"label": "European Alternatives", "url": "https://european-alternatives.eu/"}]', 1, 5);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('subs-switch-music', 'subscriptions', '6a8578266d00107b3bf3f483', 'Switch your music subscription', 'Same playlists, different company.', 'Most services let you export playlists before cancelling, so the switch doesn''t cost you your library.', 'Substitute', 'Moderate', '10-30 Minutes', 'Anywhere', '[0, 50, 120]', '[]', 1, 6);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('banking-open-credit-union', 'money-banking', '6a8578266d00107b3bf3f485', 'Open an account at a credit union', 'Member-owned, not shareholder-owned.', 'Opening the account is the fast part — most of the work is deciding it''s worth doing. Ten to thirty minutes, often online.', 'Substitute', 'Moderate', '10-30 Minutes', 'Anywhere', '[]', '[{"label": "Prison Free Funds", "url": "https://prisonfreefunds.org"}]', 0, 1);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('banking-move-primary-checking', 'money-banking', '6a8578266d00107b3bf3f485', 'Move your primary checking account', 'Your everyday deposits are working capital your bank lends and invests.', 'Direct deposit and autopay migration is the actual work here — most banks have a switch kit that automates it.', 'Withdraw', 'Moderate', '1-2 Hours', 'Anywhere', '[]', '[{"label": "Prison Free Funds", "url": "https://prisonfreefunds.org"}]', 1, 2);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('banking-switch-credit-card', 'money-banking', '6a8578266d00107b3bf3f485', 'Switch to a credit-union-issued card', 'Same rails, different lender behind the card.', 'Update your saved payment methods after the new card arrives — that''s the whole switch.', 'Substitute', 'Moderate', '10-30 Minutes', 'Anywhere', '[]', '[]', 1, 3);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('banking-ask-lending-priorities', 'money-banking', '6a8578266d00107b3bf3f485', 'Ask your bank one direct question', 'What do they lend to, and would they say so in writing?', 'A single, specific, written question to your bank''s customer service or branch — about their lending priorities — creates a record and costs one email.', 'Pressure', 'Easy', '10-30 Minutes', 'Anywhere', '[]', '[]', 0, 4);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('banking-review-fees', 'money-banking', '6a8578266d00107b3bf3f485', 'Review and cut your bank fees', 'Monthly maintenance, overdraft, and ATM fees add up quietly.', 'Most fee schedules are negotiable or avoidable once you know they exist — call and ask, or switch to an account type without them.', 'Withdraw', 'Easy', '10-30 Minutes', 'Anywhere', '[0, 60, 120]', '[]', 0, 5);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('banking-detention-financing', 'money-banking', '6a21eeb088fbdde6b3493f8e', 'Check who finances ICE detention', 'Some banks have arranged billions for private detention operators.', 'Look up whether your bank appears on financing lists for private prison and detention operators, and move your account if it does. If you do, tell them why.', 'Withdraw', 'Moderate', '10-30 Minutes', 'US only', '[]', '[{"label": "Boycott Citizens", "url": "https://www.boycottcitizens.org"}]', 0, 6);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('invest-ask-pension-holdings', 'investments', '6a8578266d00107b3bf3f487', 'Ask what your pension holds', 'You may own what you''re boycotting.', 'Retirement plans are handed to you with a default fund lineup nobody explains. Request the holdings list — it''s a right, not a favor.', 'Build', 'Moderate', '10-30 Minutes', 'Anywhere', '[]', '[{"label": "As You Sow", "url": "https://www.asyousow.org/"}]', 0, 1);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('invest-request-fund-lineup', 'investments', '6a8578266d00107b3bf3f487', 'Request your plan''s fund lineup in writing', 'A paper trail beats a phone call you can''t cite later.', 'Most providers have a standard disclosure document — ask for it by name so you have something concrete to review or share.', 'Build', 'Easy', '10-30 Minutes', 'Anywhere', '[]', '[]', 0, 2);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('invest-move-discretionary-account', 'investments', '6a8578266d00107b3bf3f487', 'Move a discretionary investment account', 'Not the whole retirement plan — just the account you control directly.', 'A brokerage or taxable account you manage yourself is the easiest one to move to a values-screened fund, since there''s no employer plan administrator in the way.', 'Withdraw', 'Advanced', '1-2 Hours', 'Anywhere', '[]', '[{"label": "As You Sow", "url": "https://www.asyousow.org/"}]', 1, 3);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('invest-learn-index-exposure', 'investments', '6a8578266d00107b3bf3f487', 'Learn what your index funds actually hold', 'A total-market fund owns almost everything, including what you''d rather not.', 'Fund fact sheets list top holdings publicly. Twenty minutes tells you what you''re already exposed to, before you decide anything about it.', 'Build', 'Easy', '10-30 Minutes', 'Anywhere', '[]', '[]', 0, 4);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('invest-ask-employer-provider', 'investments', '6a8578266d00107b3bf3f487', 'Ask your employer about the plan provider', 'HR can usually name the administrator and the fund menu.', 'One email to HR or benefits, asking who administers the retirement plan and what the default fund is, on the record.', 'Pressure', 'Easy', '10-30 Minutes', 'Anywhere', '[]', '[]', 0, 5);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('travel-redirect-booking', 'travel', '6a85786ec61c6c719566ef1c', 'Redirect one booking', 'One trip, rerouted to a different destination or operator.', 'Inbound tourism spending shows up in public monthly statistics — one redirected booking is a real, countable number, not a symbolic gesture.', 'Withdraw', 'Moderate', '1-2 Hours', 'Anywhere', '[0, 200, 500]', '[]', 0, 1);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('travel-switch-rental-car', 'travel', '6a85786ec61c6c719566ef1c', 'Switch your rental car provider', 'Compare on the way to checkout — it''s usually the same three clicks.', 'Rental comparison sites make this close to a wash on price, so the switch mostly costs the habit of always picking the same one.', 'Substitute', 'Easy', '10-30 Minutes', 'Anywhere', '[0, 40, 90]', '[]', 0, 2);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('travel-choose-rail', 'travel', '6a85786ec61c6c719566ef1c', 'Choose rail or transit over a flagged airline', 'For one trip where it''s realistically an option.', 'Doesn''t have to be every trip — one deliberate substitution, on a route where rail is genuinely viable, is the whole action.', 'Substitute', 'Moderate', '1-2 Hours', 'Anywhere', '[]', '[]', 0, 3);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('travel-delay-vehicle-purchase', 'travel', '6a85786ec61c6c719566ef1c', 'Delay a discretionary vehicle purchase', 'Public, peaceful, and about spending — nothing else.', 'Any acknowledgment of vehicle-brand demonstrations in this app follows the same non-violence framing as the source campaign: peaceful, no property damage, focused on spending decisions.', 'Withdraw', 'Advanced', 'Varies', 'Anywhere', '[]', '[{"label": "Tesla Takedown (peaceful action network)", "url": "https://actionnetwork.org/event_campaigns/teslatakedown"}]', 0, 4);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('travel-log-past-redirect', 'travel', '6a85786ec61c6c719566ef1c', 'Log a trip you already redirected', 'Already changed a booking? Make it count here too.', 'If you''d already made this call before finding this list, log it — the collective count only works if real, already-taken actions get counted.', 'Build', 'Easy', '5 Minutes', 'Anywhere', '[]', '[]', 0, 5);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('inst-ask-workplace-procurement', 'institutions', '6a85786ec61c6c719566ef1e', 'Ask what your workplace buys', 'One organisation switching outweighs a thousand individual consumers.', 'Your employer, council, union, club, or congregation all sign contracts. Asking who holds them, and from whom, is the first step — someone has to raise it.', 'Pressure', 'Moderate', '1-2 Hours', 'Anywhere', '[]', '[{"label": "Eurostack", "url": "https://eurostack.eu/"}]', 0, 1);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('inst-propose-procurement-change', 'institutions', '6a85786ec61c6c719566ef1e', 'Propose one procurement change', 'A specific vendor swap, put forward formally.', 'A written proposal — to a workplace committee, an HOA board, a club, or a congregation — naming one specific contract to reconsider.', 'Pressure', 'Advanced', '1 Day', 'Anywhere', '[]', '[]', 0, 2);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('inst-ask-local-government', 'institutions', '6a85786ec61c6c719566ef1e', 'Ask your local government one procurement question', 'Council contracts are public record — asking makes that visible.', 'A single specific question, submitted through a council''s public comment or contact process, about a specific contract or vendor relationship.', 'Pressure', 'Moderate', '1-2 Hours', 'Anywhere', '[]', '[]', 0, 3);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('inst-attend-meeting', 'institutions', '6a85786ec61c6c719566ef1e', 'Attend one institutional or shareholder meeting', 'Public comment periods and shareholder meetings are open for a reason.', 'Council sessions, shareholder meetings, and public hearings usually have an open comment window — showing up, even without speaking, is the action.', 'Pressure', 'Advanced', '1 Day', 'Anywhere', '[]', '[]', 0, 4);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('inst-submit-public-comment', 'institutions', '6a85786ec61c6c719566ef1e', 'Submit a public comment on a purchasing decision', 'Written, on the record, tied to a specific decision.', 'Most public bodies have a formal comment process for procurement decisions — using it creates a record that a hallway conversation doesn''t.', 'Pressure', 'Moderate', '1-2 Hours', 'Anywhere', '[]', '[]', 0, 5);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('inst-register-to-vote', 'institutions', '6a85786ec61c6c719566ef1e', 'Register to vote, or confirm you''re still registered', 'Institutional power runs through elected ones too.', 'A registration check takes minutes and is the highest-leverage single action most people can take toward the institutions that set the rules everything else operates under.', 'Build', 'Easy', '5 Minutes', 'US only', '[]', '[]', 0, 6);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('inst-share-ownership-research', 'institutions', '6a85786ec61c6c719566ef1e', 'Share brand-ownership research with a coworker', 'The information only spreads if someone hands it over.', 'Send one person the ownership research you already did — a link, a screenshot, a two-line summary. That''s the whole action.', 'Build', 'Easy', '5 Minutes', 'Anywhere', '[]', '[]', 0, 7);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('attn-quit-one-platform', 'attention', '6a85786ec61c6c719566ef20', 'Delete or deactivate one attention platform', 'Your attention, your posts, and your data are the product.', 'Withdraw the supply. A single platform, deleted or deactivated, is the whole action — no need to leave everything at once.', 'Withdraw', 'Easy', '5 Minutes', 'Anywhere', '[]', '[{"label": "uBlock Origin", "url": "https://ublockorigin.com/"}]', 1, 1);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('attn-turn-off-algorithmic-feed', 'attention', '6a85786ec61c6c719566ef20', 'Switch to a chronological feed', 'Where the setting exists, the algorithm is optional.', 'Most major platforms still offer a non-algorithmic timeline option, buried a few taps deep. Turning it on changes what gets fed to you, immediately.', 'Withdraw', 'Easy', '5 Minutes', 'Anywhere', '[]', '[]', 0, 2);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('attn-pay-for-news', 'attention', '6a85786ec61c6c719566ef20', 'Move your news reading to a source you pay directly', 'Fund the alternative with what an ad-funded feed used to cost you.', 'A direct subscription to a source you trust replaces an ad-funded feed''s business model with one that doesn''t depend on holding your attention as long as possible.', 'Substitute', 'Moderate', '10-30 Minutes', 'Anywhere', '[0, 50, 100]', '[]', 1, 3);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('attn-set-daily-limit', 'attention', '6a85786ec61c6c719566ef20', 'Set a hard daily limit on one platform', 'A device-level limit, not a promise to yourself.', 'Phone-level app timers are enforced by the device, not willpower — set one on the platform you use most.', 'Withdraw', 'Easy', '5 Minutes', 'Anywhere', '[]', '[]', 0, 4);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('attn-unfollow-advertiser-feed', 'attention', '6a85786ec61c6c719566ef20', 'Unfollow one advertiser-funded feed', 'One account, one unfollow, one fewer ad impression counted against you.', 'Small and specific on purpose — the smallest version of this action still counts.', 'Withdraw', 'Easy', '5 Minutes', 'Anywhere', '[]', '[]', 0, 5);
INSERT INTO actions (id, category_id, webflow_item_id, name, short_description, long_description_html, mode, effort, time_estimate, availability, money_presets, helpful_links, is_time_served, sort_order) VALUES ('attn-week-without-app', 'attention', '6a85786ec61c6c719566ef20', 'Delete one attention app for a week', 'A real, checkable week off — not a vague intention to cut back.', 'Delete the app, not just the habit — for one full week. Check back in when the week''s up.', 'Withdraw', 'Moderate', '1 Day', 'Anywhere', '[]', '[]', 1, 6);